    documentHandler.handleExtensionObject(new PDFDictionaryAttachment(dictionaryExtension));
    documentHandler.endPage();
    Assert.assertTrue(bos.toString(), bos.toString().contains("/PieceInfo << /a << >> /LastModified (D:"));
}

